"""One shared inverse ruled-chart evaluator and runtime crown reconciliation."""
from .backend_runtime import Graph, V, choose, bounded, smooth, named, remove, repeat, rm
from . import oblique


def build_coordinates(*, max_pieces=3):
    suffix=' / Five pieces' if max_pieces==5 else ''
    g = Graph('Street Blosm / Ruled chart coordinates'+suffix)
    g.socket('Patches', 'NodeSocketGeometry'); g.socket('Pieces', 'NodeSocketGeometry')
    g.socket('Index', 'NodeSocketInt'); g.socket('t', 'NodeSocketFloat')
    g.socket('K', 'NodeSocketVector', 'OUTPUT'); g.socket('D', 'NodeSocketVector', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    t, index = V(g, inp.outputs['t']), V(g, inp.outputs['Index'])
    K = rm.bezier(g, inp.outputs['Patches'], index, t)
    O = rm.outer(g, inp.outputs['Patches'], inp.outputs['Pieces'], index, t,max_pieces=max_pieces)
    out = g.node('NodeGroupOutput')
    g.bind(g.xyz(*K), out.inputs['K']); g.bind(g.xyz(*[o-k for o, k in zip(O,K)]), out.inputs['D'])
    return g.g


def build_sector(coordinates, *, suffix=''):
    g = Graph('Street Blosm / Invert one ruled sector'+suffix)
    for n in ('Geometry', 'Arms', 'Patches', 'Pieces'): g.socket(n, 'NodeSocketGeometry')
    g.socket('Index', 'NodeSocketInt')
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    inp = g.node('NodeGroupInput'); patches, arms = inp.outputs['Patches'], inp.outputs['Arms']
    index = V(g, inp.outputs['Index'])
    x, y, _ = g.separate(g.position())

    def chart(t):
        n = g.node('GeometryNodeGroup', 'Analytic K(t), O(t)-K(t)'); n.node_tree = coordinates
        for key in ('Patches','Pieces','Index'): g.bind(inp.outputs[key], n.inputs[key])
        g.bind(t, n.inputs['t'])
        return g.separate(V(g,n.outputs['K']))[:2], g.separate(V(g,n.outputs['D']))[:2]

    def residual(t):
        K,D = chart(t)
        return (x-K[0])*D[1]-(y-K[1])*D[0]

    g.section('Per-point root brackets')
    flo, fhi = residual(0.), residual(1.)
    geo = g.store(inp.outputs['Geometry'], '_shared_bracket',
                  1.-g.math('GREATER_THAN', flo*fhi, 0.), 'POINT', 'BOOLEAN')
    geo = g.store(geo, '_shared_interval', g.xyz(0.,1.,flo), 'POINT', 'FLOAT_VECTOR')
    start,end = repeat(g, geo, 24, 'Bisection')
    lo, hi, flow = g.separate(named(g,'_shared_interval','FLOAT_VECTOR'))
    mid = (lo+hi)*.5; fm = residual(mid)
    same = g.math('GREATER_THAN',flow*fm,0.)
    interval = g.xyz(choose(g,same,mid,lo),choose(g,same,hi,mid),choose(g,same,fm,flow))
    step = g.store(start.outputs['Geometry'],'_shared_interval',interval,'POINT','FLOAT_VECTOR')
    g.bind(step,end.inputs['Geometry'])
    lo,hi,_ = g.separate(named(g,'_shared_interval','FLOAT_VECTOR'))
    t=(lo+hi)*.5; K,D=chart(t)
    v=((x-K[0])*D[0]+(y-K[1])*D[1])/(D[0]*D[0]+D[1]*D[1])
    valid=named(g,'_shared_bracket','BOOLEAN')*(1.-g.math('LESS_THAN',v,-3e-6))*(1.-g.math('GREATER_THAN',v,1.+3e-6))
    first=rm.read(g,patches,'first_arm',index,'INT');second=rm.read(g,patches,'second_arm',index,'INT')
    f=rm.read(g,arms,'left_plateau_fraction',first);s=rm.read(g,arms,'right_plateau_fraction',second)
    vv=bounded(g,v);w=smooth(t)
    phi=(1.-w)*rm.profile(g,f,vv)+w*rm.profile(g,s,vv)
    final=g.store(end.outputs['Geometry'],'profile_fraction',
                  choose(g,valid,phi,named(g,'profile_fraction')),'POINT','FLOAT')
    out=g.node('NodeGroupOutput');g.bind(final,out.inputs['Geometry'])
    return g.g


def build_fraction(*, max_pieces=3):
    suffix=' / Five pieces' if max_pieces==5 else ''
    sector=build_sector(build_coordinates(max_pieces=max_pieces),suffix=suffix)
    g=Graph('Street Blosm / Analytic surface fraction'+suffix)
    for n in ('Geometry','Arms','Patches','Pieces'):g.socket(n,'NodeSocketGeometry')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput')
    view=g.node('GeometryNodeSeparateGeometry','Sector records');view.domain='POINT'
    g.bind(inp.outputs['Patches'],view.inputs['Geometry'])
    g.bind(rm.equal(g,named(g,'kind','INT'),1)*(1.-named(g,'plateau_edge','BOOLEAN')),view.inputs['Selection'])
    sectors=V(g,view.outputs['Selection'])
    geo=g.store(inp.outputs['Geometry'],'profile_fraction',1.,'POINT','FLOAT')
    start,end=repeat(g,geo,rm.count(g,sectors),'Every sector in cyclic order')
    n=g.node('GeometryNodeGroup','Invert the current sector');n.node_tree=sector
    g.bind(start.outputs['Geometry'],n.inputs['Geometry']);g.bind(start.outputs['Iteration'],n.inputs['Index'])
    g.bind(sectors,n.inputs['Patches'])
    for key in ('Arms','Pieces'):g.bind(inp.outputs[key],n.inputs[key])
    g.bind(n.outputs['Geometry'],end.inputs['Geometry'])
    phi=choose(g,named(g,'fixed_xy','BOOLEAN'),named(g,'original_phi'),named(g,'profile_fraction'))
    phi=choose(g,named(g,'outer_boundary','BOOLEAN'),0.,phi)
    geo=g.store(end.outputs['Geometry'],'profile_fraction',phi,'POINT','FLOAT')
    for name in ('_shared_interval','_shared_bracket'):geo=remove(g,geo,name)
    out=g.node('NodeGroupOutput');g.bind(geo,out.inputs['Geometry'])
    return g.g


def build_crown(*, suffix=''):
    """Retain ordered products excluding i, including exact zero mouth distances."""
    g=Graph('Street Blosm / Incoming crown reconciliation'+suffix)
    for n in ('Geometry','Arms','Header'):g.socket(n,'NodeSocketGeometry')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');arms=inp.outputs['Arms'];header=inp.outputs['Header']
    count=rm.count(g,arms);ceiling=rm.read(g,header,'ceiling',0)
    scale=rm.read(g,header,'crown_weight_scale_m',0)
    geo=g.store(inp.outputs['Geometry'],'_shared_sumw',0.,'POINT','FLOAT')
    geo=g.store(geo,'_shared_sumwh',0.,'POINT','FLOAT')
    outer,outer_end=repeat(g,geo,count,'Crown weight for each arm')
    current=V(g,outer.outputs['Iteration'])
    geo=g.store(outer.outputs['Geometry'],'_shared_weight',1.,'POINT','FLOAT')
    inner,inner_end=repeat(g,geo,count,'Product of all other arm distances')
    j=V(g,inner.outputs['Iteration'])
    x,y,_=g.separate(g.position())
    ox,oy,_=g.separate(rm.read(g,arms,'origin',j,'FLOAT_VECTOR'))
    x,y=x-ox,y-oy
    tx,ty,_=g.separate(rm.read(g,arms,'tangent',j,'FLOAT_VECTOR'))
    nx,ny,_=g.separate(rm.read(g,arms,'right',j,'FLOAT_VECTOR'))
    station=rm.read(g,arms,'inner_station',j);width=rm.read(g,arms,'width',j)
    ds=g.math('MAXIMUM',station-(x*tx+y*ty),0.)
    dq=g.math('MAXIMUM',g.math('ABSOLUTE',x*nx+y*ny)-width*.5,0.)
    query_station=g.math('MAXIMUM',station,x*tx+y*ty)
    left=oblique.edge_at(g,arms,j,'left',query_station)
    right=oblique.edge_at(g,arms,j,'right',query_station)
    lo=(left[0]-ox)*nx+(left[1]-oy)*ny
    hi=(right[0]-ox)*nx+(right[1]-oy)*ny
    q=x*nx+y*ny
    dq=choose(g,rm.read(g,arms,'oblique',j,'BOOLEAN'),g.math('MAXIMUM',0.,g.math('MAXIMUM',lo-q,q-hi)),dq)
    rho=(ds*ds+dq*dq)/(scale*scale)
    same=rm.equal(g,current,j)
    weight=named(g,'_shared_weight')*choose(g,same,1.,rho)
    step=g.store(inner.outputs['Geometry'],'_shared_weight',weight,'POINT','FLOAT')
    g.bind(step,inner_end.inputs['Geometry'])
    weight=named(g,'_shared_weight')
    deficit=ceiling-rm.read(g,arms,'rise',current)
    geo=g.store(inner_end.outputs['Geometry'],'_shared_sumw',named(g,'_shared_sumw')+weight,'POINT','FLOAT')
    geo=g.store(geo,'_shared_sumwh',named(g,'_shared_sumwh')+weight*deficit,'POINT','FLOAT')
    g.bind(geo,outer_end.inputs['Geometry'])
    geo=g.store(outer_end.outputs['Geometry'],'crown_amplitude',
                ceiling-named(g,'_shared_sumwh')/named(g,'_shared_sumw'),'POINT','FLOAT')
    for name in ('_shared_sumw','_shared_sumwh','_shared_weight'):geo=remove(g,geo,name)
    out=g.node('NodeGroupOutput');g.bind(geo,out.inputs['Geometry'])
    return g.g
